/**
 * Inject the #157-approved budget declarations (DEC-DE-157-002, V1 design
 * values) into a workspace organization file generated by
 * `digital-employee workspace init` (the origin/main template predates the
 * budget field). Idempotent; fails closed on unknown positions.
 *
 * Usage: node scripts/inject-example-budget.mjs <path/to/organization.v1alpha1.json>
 */
import fs from "node:fs";

const BUDGETS = {
  "repo-owner": {
    perTask: { tokens: 40000, iterations: 12 },
    perDay: { tokens: 400000, iterations: 96 },
  },
  "issue-researcher": {
    perTask: { tokens: 20000, iterations: 8 },
    perDay: { tokens: 200000, iterations: 64 },
  },
  "release-engineer": {
    perTask: { tokens: 20000, iterations: 8 },
    perDay: { tokens: 200000, iterations: 64 },
  },
  "community-operator": {
    perTask: { tokens: 20000, iterations: 8 },
    perDay: { tokens: 200000, iterations: 64 },
  },
};

const file = process.argv[2];
if (!file) {
  console.error("usage: inject-example-budget.mjs <organization.v1alpha1.json>");
  process.exit(1);
}
const org = JSON.parse(fs.readFileSync(file, "utf8"));
if (!Array.isArray(org.roles)) {
  console.error("not an organization file");
  process.exit(1);
}
for (const role of org.roles) {
  const budget = BUDGETS[role.id];
  if (!budget) {
    console.error(`no budget mapping for position: ${role.id}`);
    process.exit(1);
  }
  role.budget = budget;
}
fs.writeFileSync(file, `${JSON.stringify(org, null, 2)}\n`, "utf8");
console.log(`budget injected: ${org.roles.length} positions -> ${file}`);
